import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:1 + n]]
    q = int(data[1 + n])
    qs = data[2 + n:2 + n + q]
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < a[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    p = lo
    out = []
    for s in qs:
        x = int(s)
        l, r = 0, p
        res = -1
        while l <= r:
            m = (l + r) // 2
            if a[m] == x:
                res = m
                break
            if a[m] < x:
                l = m + 1
            else:
                r = m - 1
        if res == -1:
            l, r = p + 1, n - 1
            while l <= r:
                m = (l + r) // 2
                if a[m] == x:
                    res = m
                    break
                if a[m] > x:
                    l = m + 1
                else:
                    r = m - 1
        out.append(res)
    print('\n'.join(map(str, out)))

